#!/usr/bin/env bash
set -euo pipefail
cd /opt/mirage
set -a
# .env contains shell-safe values generated by prepare_server.py.
. ./.env
set +a
response="$(curl --fail --silent --show-error --get \
  --data-urlencode "domains=${DUCKDNS_SUBDOMAIN}" \
  --data-urlencode "token=${DUCKDNS_TOKEN}" \
  --data-urlencode "ip=" \
  "https://www.duckdns.org/update")"
if [[ "$response" != "OK" ]]; then
  echo "DuckDNS update returned: ${response}" >&2
  exit 1
fi
printf '%s\n' "$response"
